package com.acaivis.controller;
import com.acaivis.dto.*; import com.acaivis.service.ProductService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductService s;public ProductController(ProductService s){this.s=s;} @GetMapping public List<ProductResponse> all(@RequestParam(defaultValue="true") boolean available){return s.findAll(available);} @GetMapping("/{id}") public ProductResponse one(@PathVariable Long id){return s.findById(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public ProductResponse create(@Valid @RequestBody ProductRequest d){return s.create(d);} @PutMapping("/{id}") public ProductResponse update(@PathVariable Long id,@Valid @RequestBody ProductRequest d){return s.update(id,d);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}}
